import sys

def main():
    data = sys.stdin.buffer.read().split()
    n, m = int(data[0]), int(data[1])
    cap = list(range(n))
    for i in range(m):
        x = int(data[2 + 2 * i])
        y = int(data[3 + 2 * i])
        if y < cap[x]:
            cap[x] = y
    for i in range(1, n):
        if cap[i - 1] + 1 < cap[i]:
            cap[i] = cap[i - 1] + 1
    for i in range(n - 2, -1, -1):
        if cap[i + 1] + 1 < cap[i]:
            cap[i] = cap[i + 1] + 1
    print(max(cap))

